using Crown.Core;

internal static class StageTwentyThreeSpecs
{
    private static void Assert(bool ok,string text){if(!ok)throw new Exception(text);}
    internal static (GameState S,Unit Ship,Unit Troop) Fixture(string model="carrack",UnitKind kind=UnitKind.Spearmen)
    {var s=StageTwentyTwoSpecs.Fixture();var ship=Engine.AddUnit(s,0,13*s.Width+12,UnitKind.Ship,model);var troop=Engine.AddUnit(s,0,s.Cities[0].Tile,kind);return(s,ship,troop);}
    private static void Board(GameState s,Unit ship,Unit troop)=>Assert(SeaTransport.Embark(s,troop.Id,ship.Id).Success,"Boarding failed");
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    public static void Run(Action<string,Action> test)
    {
        test("Naval carrying capacity scales by model and heavy troops use two slots",()=>{var(s,ship,u)=Fixture("coastal_galley",UnitKind.Cavalry);Assert(SeaTransport.Capacity(ship)==1&&SeaTransport.Weight(u)==2&&!SeaTransport.Embark(s,u.Id,ship.Id).Success,"Galley overloaded");ship.ModelId="carrack";ship.Actions=ship.MaxActions;Board(s,ship,u);Assert(SeaTransport.Used(s,ship)==2&&SeaTransport.Capacity(ship)==2,"Heavy load wrong");ship.ModelId="destroyer";Assert(SeaTransport.Capacity(ship)==4,"Modern capacity missing");});
        test("Embarkation preserves identity and health while spending actions and clearing orders",()=>{var(s,ship,u)=Fixture();u.Health=73;u.Experience=4;u.Order=MilitaryOrder.Fortify;u.FortificationTurns=2;int count=s.Units.Count;Board(s,ship,u);Assert(s.Units.Count==count&&u.EmbarkedOnId==ship.Id&&u.Tile==ship.Tile&&u.Health==73&&u.Experience==4&&u.Actions==0&&ship.Actions==ship.MaxActions-1&&u.Order==MilitaryOrder.None,"Boarding duplicated healed or failed to charge");Valid(s);});
        test("Rejected boarding is atomic for insufficient capacity movement ownership and port access",()=>{foreach(int mode in Enumerable.Range(0,6)){var(s,ship,u)=Fixture();switch(mode){case 0:ship.Actions=0;break;case 1:u.Actions=0;break;case 2:ship.Owner=1;break;case 3:s.Cities[0].Buildings.Remove(Navy.Port);break;case 4:u.Tile=s.Cities[2].Tile;break;case 5:u.EscortCaravanId=99;break;}string before=SaveGame.Serialize(s);Assert(!SeaTransport.Embark(s,u.Id,ship.Id).Success&&SaveGame.Serialize(s)==before,"Illegal boarding mutated state");}});
        test("Ships cannot be nested inside ships and a passenger cannot board twice",()=>{var(s,ship,u)=Fixture();var other=Engine.AddUnit(s,0,ship.Tile,UnitKind.Ship,"carrack");Assert(!SeaTransport.Embark(s,other.Id,ship.Id).Success,"Nested ship accepted");Board(s,ship,u);string before=SaveGame.Serialize(s);Assert(!SeaTransport.Embark(s,u.Id,other.Id).Success&&SaveGame.Serialize(s)==before,"Passenger duplicated");});
        test("A blocked port cannot embark new troops",()=>{var(s,ship,u)=Fixture();s.Relation(0,1).War=true;Engine.AddUnit(s,1,13*s.Width+11,UnitKind.Ship,"coastal_galley");Assert(SeaTransport.BoardError(s,u,ship)!=null,"Blocked port embarked troops");});
        test("Actual ship movement carries every passenger without extra independent movement",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);int target=13*s.Width+13;Assert(Engine.Move(s,ship.Id,target).Success&&ship.Tile==target&&u.Tile==target&&u.Actions==0,"Passenger did not follow actual movement");Valid(s);});
        test("Passengers cannot move march attack or create military orders independently",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);string before=SaveGame.Serialize(s);Assert(!Engine.Move(s,u.Id,s.Cities[0].Tile).Success&&!Engine.OrderMove(s,u.Id,s.Cities[0].Tile).Success&&!Engine.PreviewAttack(s,u.Id,s.Cities[1].Tile).Valid&&!Engine.SetMilitaryOrder(s,u.Id,MilitaryOrder.Recover).Success&&SaveGame.Serialize(s)==before,"Passenger acted from aboard");});
        test("An embarked scout does not extend the carrier's reconnaissance radius",()=>{var(s,ship,u)=Fixture("carrack",UnitKind.Scout);Board(s,ship,u);ship.Tile=u.Tile=14*s.Width+30;s.InvalidateLogistics();var distant=s.Tiles.First(t=>World.Distance(t,s.Tiles[ship.Tile])==4&&s.Cities.Where(c=>c.Owner==0).All(c=>World.Distance(t,s.Tiles[c.Tile])>3));Assert(!Engine.Visible(s).Contains(distant.Id)&&MilitaryStrategy.Sight(s,0).SetEquals(Engine.Visible(s)),"Cargo provided phantom sight");});
        test("Passengers use carrier supply and pay their normal unit maintenance",()=>{var(s,ship,u)=Fixture();double cost=Engine.Economy(s,0).ArmyCost;Board(s,ship,u);Assert(Engine.Supplied(s,u)&&Engine.Economy(s,0).ArmyCost==cost,"Cargo supply or maintenance wrong");s.Cities[0].Buildings.Remove(Navy.Port);s.InvalidateLogistics();Assert(!Engine.Supplied(s,u),"Passenger invented a supply route");});
        test("EndTurn does not heal passengers or grant them movement while at sea",()=>{var(s,ship,u)=Fixture();u.Health=60;Board(s,ship,u);Assert(Engine.EndTurn(s).Success&&u.Health==60&&u.Actions==0&&u.EmbarkedOnId==ship.Id,"Onboard turn granted actions or healing");Valid(s);});
        test("Landing spends ship movement and leaves the soldier exhausted until the next turn",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);double actions=ship.Actions;Assert(SeaTransport.Disembark(s,u.Id,s.Cities[0].Tile).Success&&u.EmbarkedOnId==null&&u.Actions==0&&ship.Actions==actions-1&&u.Tile==s.Cities[0].Tile,"Landing bypassed action costs");Assert(Engine.EndTurn(s).Success&&u.Actions==u.MaxActions,"Landed soldier never became ready");Valid(s);});
        test("Landing requires a neighboring passable discovered and empty shore",()=>{foreach(int mode in Enumerable.Range(0,5)){var(s,ship,u)=Fixture();Board(s,ship,u);int target=s.Cities[0].Tile;switch(mode){case 0:target=ship.Tile;break;case 1:target=s.Cities[2].Tile;break;case 2:s.Tiles[target].Explored=false;break;case 3:Engine.AddUnit(s,1,target,UnitKind.Spearmen);break;case 4:ship.Actions=0;break;}string before=SaveGame.Serialize(s);Assert(!SeaTransport.Disembark(s,u.Id,target).Success&&SaveGame.Serialize(s)==before,"Bad landing mutated state");}});
        test("Military landings respect peaceful borders and allow empty hostile shores during war",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);int target=s.Cities[0].Tile+1;s.Tiles[target].Owner=1;Assert(!SeaTransport.Disembark(s,u.Id,target).Success,"Peaceful border ignored");s.Relation(0,1).War=true;Assert(SeaTransport.Disembark(s,u.Id,target).Success&&u.Actions==0&&s.Tiles[target].Owner==1,"Hostile shore landing failed or captured territory for free");});
        test("Settlers cannot land on foreign owned shores even during war",()=>{var(s,ship,u)=Fixture("carrack",UnitKind.Settler);Board(s,ship,u);int target=s.Cities[0].Tile+1;s.Tiles[target].Owner=1;s.Relation(0,1).War=true;Assert(!SeaTransport.Disembark(s,u.Id,target).Success,"Settler seized foreign shore");});
        test("Enemy cities must be captured on land rather than taken by a landing command",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);s.Relation(0,1).War=true;ship.Tile=u.Tile=13*s.Width+20;Assert(!SeaTransport.Disembark(s,u.Id,s.Cities[1].Tile).Success,"Landing captured a city");});
        test("Passengers never become independent field garrisons or visible enemy targets",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);Assert(!MilitaryStrategy.Combatant(u)&&!MilitaryStrategy.Plan(s,0).Assignments.Any(a=>a.UnitId==u.Id),"Cargo became a field unit");ship.Owner=u.Owner=1;s.Relation(0,1).War=true;s.Units.Remove(u);s.Units.Insert(0,u);var gun=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Archer);var preview=Engine.PreviewAttack(s,gun.Id,ship.Tile);Assert(preview.Valid&&preview.Target==UnitModels.Name(ship),"Combat targeted cargo instead of its carrier");});
        test("Sinking a loaded ship removes its complete manifest and records the loss",()=>{var(s,ship,u)=Fixture();var other=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Scout);Board(s,ship,u);Board(s,ship,other);ship.Health=1;s.Relation(0,1).War=true;var attacker=Engine.AddUnit(s,1,13*s.Width+13,UnitKind.Ship,"carrack");Assert(Engine.Move(s,attacker.Id,ship.Tile).Success&&!s.Units.Contains(ship)&&!s.Units.Contains(u)&&!s.Units.Contains(other),"Sunk passengers survived or detached");Valid(s);});
        test("An insolvent carrier desertion never leaves dangling passengers",()=>{var(s,ship,u)=Fixture();for(int i=0;i<60;i++)Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Spearmen);var carrier=Engine.AddUnit(s,0,ship.Tile,UnitKind.Ship,"carrack");Board(s,carrier,u);s.Turn=3;s.Player.Gold=0;s.Player.Tax=0;Assert(Engine.EndTurn(s).Success&&!s.Units.Contains(carrier)&&!s.Units.Contains(u),"Desertion abandoned an invalid manifest");Valid(s);});
        test("Passengers and ships cannot provide phantom guards for land caravans",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);var contract=new TradeContract{Buyer=0,Seller=2};int coast=s.Cities[0].Tile+1;Assert(!Caravans.Guarded(s,contract,coast),"Cargo or ship guarded a land route");s.Relation(0,1).War=true;ship.Owner=u.Owner=1;Assert(!Caravans.Threatened(s,contract,coast),"Cargo threatened a land route");});
        test("A peace treaty withdraws a loaded carrier onto water with its manifest intact",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);s.Relation(0,1).War=true;s.Relation(0,1).Trust=100;s.Factions[1].WarWeariness=100;ship.Tile=u.Tile=13*s.Width+20;s.InvalidateLogistics();Assert(Engine.ProposePeace(s,1,200).Success,"Peace proposal rejected");s.Turn+=2;PeaceCouncil.Tick(s);Assert(!s.Relation(0,1).War&&Navy.Water(s.Tiles[ship.Tile])&&ship.Tile==u.Tile&&u.EmbarkedOnId==ship.Id&&ship.Actions==0,"Treaty stranded or split the carrier");Valid(s);});
        test("A real crossing and two landings can establish a coastal colony on a new shore",()=>{var(s,ship,settler)=Fixture("carrack",UnitKind.Settler);var guard=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Spearmen);Board(s,ship,settler);Board(s,ship,guard);Assert(Engine.OrderMove(s,ship.Id,15*s.Width+12).Success,"Crossing order failed");s.PendingEvent=null;Assert(Engine.EndTurn(s).Success,"Crossing turn failed");Assert(SeaTransport.Disembark(s,settler.Id,16*s.Width+12).Success&&SeaTransport.Disembark(s,guard.Id,16*s.Width+13).Success,"New shore landing failed");Assert(!Engine.FoundCity(s,settler.Id).Success,"Exhausted settler founded early");s.PendingEvent=null;Assert(Engine.EndTurn(s).Success&&Engine.FoundCity(s,settler.Id).Success&&s.Cities.Count(c=>c.Owner==0)==2,"Colony failed after actual voyage");Valid(s);});
        test("AI transports a settler and founds a colony through ordinary economic turns",()=>{var s=StageTwentyTwoSpecs.Fixture();var city=s.Cities[1];var ship=Engine.AddUnit(s,1,13*s.Width+20,UnitKind.Ship,"carrack");Engine.AddUnit(s,1,city.Tile,UnitKind.Settler);for(int i=0;i<12&&s.Cities.Count(c=>c.Owner==1)<2;i++){s.PendingEvent=null;Assert(Engine.EndTurn(s).Success,"AI expedition turn failed");}Assert(s.Cities.Count(c=>c.Owner==1)>=2&&s.Units.All(u=>u.EmbarkedOnId==null||u.Tile==s.Units.Single(v=>v.Id==u.EmbarkedOnId).Tile),"AI colony transport stalled");Valid(s);});
        test("Wartime AI boarding retains a land defender at its embarkation city",()=>{var s=StageTwentyTwoSpecs.Fixture();s.Relation(0,1).War=true;var city=s.Cities[1];var ship=Engine.AddUnit(s,1,13*s.Width+20,UnitKind.Ship,"carrack");Engine.AddUnit(s,1,city.Tile,UnitKind.Spearmen);Engine.AddUnit(s,1,city.Tile,UnitKind.Spearmen);Engine.RunTransportAi(s,1);Assert(SeaTransport.Passengers(s,ship).Count()==1&&s.Units.Any(u=>u.Owner==1&&SeaTransport.Active(u)&&u.Kind==UnitKind.Spearmen&&u.Tile==city.Tile),"AI emptied its port garrison");});
        test("The transport AI cannot commandeer the player's ships or passengers",()=>{var(s,ship,u)=Fixture();string before=SaveGame.Serialize(s);Engine.RunTransportAi(s,0);Assert(SaveGame.Serialize(s)==before,"Player transport automated without an order");});
        test("Current saves preserve cargo identity and deterministic continuation across a voyage",()=>{var(s,ship,u)=Fixture();Board(s,ship,u);Engine.OrderMove(s,ship.Id,13*s.Width+17);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));Assert(copy.Version==SaveGame.CurrentVersion&&copy.Units.Single(v=>v.Id==u.Id).EmbarkedOnId==ship.Id,"Cargo manifest lost");for(int i=0;i<3;i++){s.PendingEvent=copy.PendingEvent=null;Assert(Engine.EndTurn(s).Success&&Engine.EndTurn(copy).Success&&SaveGame.Serialize(s)==SaveGame.Serialize(copy),"Transport future diverged");}});
        test("V21 migration preserves existing ships and ports without inventing a manifest",()=>{var(s,ship,u)=Fixture();s.Version=21;var old=System.Text.Json.Nodes.JsonNode.Parse(SaveGame.Serialize(s))!;foreach(var node in old["Units"]!.AsArray())node!.AsObject().Remove("EmbarkedOnId");string json=old.ToJsonString();var loaded=SaveGame.Deserialize(json);Assert(loaded.Version==SaveGame.CurrentVersion&&loaded.Units.Count==s.Units.Count&&loaded.Units.All(SeaTransport.Active)&&loaded.Cities[0].Buildings.Contains(Navy.Port),"Migration invented passengers");string dir=Path.Combine(Path.GetTempPath(),"crown-transport-"+Guid.NewGuid());Directory.CreateDirectory(dir);string path=Path.Combine(dir,"campaign.crown");try{File.WriteAllText(path,json);SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v21.bak")==json&&SaveGame.Read(path).Version==SaveGame.CurrentVersion,"V21 predecessor backup missing");}finally{foreach(string file in new[]{path,path+".tmp",path+".v21.bak"})File.Delete(file);Directory.Delete(dir);}});
        test("Save validation rejects forged carriers capacity positions orders and old format cargo",()=>{foreach(int mode in Enumerable.Range(0,8)){var(s,ship,u)=Fixture();Board(s,ship,u);switch(mode){case 0:u.EmbarkedOnId=9999;break;case 1:u.EmbarkedOnId=u.Id;break;case 2:u.Owner=1;break;case 3:u.Tile=s.Cities[0].Tile;break;case 4:u.Actions=1;break;case 5:u.Destination=s.Cities[0].Tile;break;case 6:ship.ModelId="coastal_galley";var extra=Engine.AddUnit(s,0,ship.Tile,UnitKind.Spearmen);extra.EmbarkedOnId=ship.Id;extra.Actions=0;break;case 7:s.Version=21;break;}bool rejected=false;try{Valid(s);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Corrupt manifest accepted");}});
    }
}
